   108	func confirmBackupOperation(cmd *cobra.Command, prompt string) (bool, error) {
   109		if _, err := fmt.Fprintf(cmd.OutOrStdout(), "%s [y/N] ", prompt); err != nil {
   110			return false, err
   111		}
   112		reader := bufio.NewScanner(cmd.InOrStdin())
   113		if !reader.Scan() {
   114			if err := reader.Err(); err != nil {
   115				return false, err
   116			}
   117			return false, nil
   118		}
   119		answer := strings.TrimSpace(reader.Text())
   120		return strings.EqualFold(answer, "y") || strings.EqualFold(answer, "yes"), nil
   121	}
