   157	// schedulePeriodicBackup schedules database backups and retention pruning.
   158	func schedulePeriodicBackup(ctx context.Context) func() error {
   159		return func() error {
   160			backup := conf.Server.Backup
   161			if backup.Path == "" || backup.Schedule == "" || backup.Count == 0 {
   162				log.Warn("Periodic database backups are DISABLED")
   163				return nil
   164			}
   165	
   166			database := db.Db()
   167			schedulerInstance := scheduler.GetInstance()
   168			log.Info("Scheduling periodic database backups", "schedule", backup.Schedule, "retention", backup.Count)
   169			err := schedulerInstance.Add(backup.Schedule, func() {
   170				path, err := database.Backup(ctx)
   171				if err != nil {
   172					log.Error("Error creating scheduled database backup", err)
   173					return
   174				}
   175				log.Info("Created scheduled database backup", "path", path)
   176				pruned, err := database.Prune(ctx)
   177				if err != nil {
   178					log.Error("Error pruning scheduled database backups", err)
   179					return
   180				}
   181				if pruned > 0 {
   182					log.Info("Pruned old database backups", "count", pruned)
   183				}
   184			})
   185			if err != nil {
   186				log.Error("Error scheduling periodic database backups", err)
   187			}
   188			return nil
   189		}
   190	}
